<template><main class="page"><header><div><p class="eyebrow">STAGE 27 COGNITIVE COMMONS</p><h1>全球认知基础设施</h1><p>证明标准、认知安全、长期治理和主权自托管的统一控制面。</p></div><el-button :icon="Refresh" circle title="刷新" :loading="loading" @click="load"/></header><section class="metrics"><div v-for="item in metrics" :key="item.key"><span>{{item.label}}</span><strong>{{overview[item.key]??0}}</strong></div></section><el-tabs v-model="tab"><el-tab-pane label="证明与认知安全" name="trust"><section class="grid"><article v-for="item in trust" :key="item.title"><el-icon><component :is="item.icon"/></el-icon><h2>{{item.title}}</h2><p>{{item.text}}</p><el-tag :type="item.type" effect="plain">{{item.state}}</el-tag></article></section></el-tab-pane><el-tab-pane label="认证套件" name="cert"><section class="form"><h2>运行跨实现证明认证</h2><p>认证要求三个独立实现使用相同格式，通过全部验证与撤回向量。</p><el-button type="primary" :icon="DocumentChecked" @click="certify">运行认证</el-button><div v-if="certificate" class="result"><span>认证状态</span><strong>{{certificate}}</strong></div></section></el-tab-pane><el-tab-pane label="长期治理" name="long"><section class="grid"><article><el-icon><TrendCharts/></el-icon><h2>十年情景规划</h2><p>技术、气候、人口、监管和供应链驱动形成可重放风险路径。</p></article><article><el-icon><ScaleToOriginal/></el-icon><h2>跨世代责任</h2><p>识别长期承诺、成本转移、生态外部性和未来群体影响。</p></article><article><el-icon><Box/></el-icon><h2>主权自托管</h2><p>断网安装、可复现构建、硬件信任根和独立安全升级。</p></article></section></el-tab-pane></el-tabs></main></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{Box,DataAnalysis,DocumentChecked,Refresh,ScaleToOriginal,TrendCharts,Warning}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import{cognitiveInfrastructureApi}from'@/api/cognitiveInfrastructure';const loading=ref(false),tab=ref('trust'),overview=reactive<Record<string,number>>({}),certificate=ref('');const metrics=computed(()=>[{key:'certifications',label:'证明认证'},{key:'constitution_upgrades',label:'宪法升级'},{key:'archives',label:'长期档案'},{key:'signals',label:'公共信号'},{key:'epistemic_blocks',label:'认知阻断'},{key:'clearing_batches',label:'清算批次'},{key:'allocations',label:'公平配给'},{key:'scenarios',label:'长期情景'},{key:'commitments',label:'代际承诺'},{key:'sovereign_builds',label:'主权构建'}]),trust=[{title:'证明互操作标准',text:'决策、策略、记忆、资源与审计证明共享认证向量。',state:'三实现认证',type:'success',icon:DocumentChecked},{title:'认知安全中心',text:'检测证据循环、来源集中、虚假共识和叙事操纵。',state:'生产门禁',type:'danger',icon:Warning},{title:'自治清算稳定器',text:'多资产逐项守恒，压力缓冲不足时触发系统熔断。',state:'守恒清算',type:'warning',icon:DataAnalysis}];async function load(){loading.value=true;try{Object.assign(overview,await cognitiveInfrastructureApi.overview())}finally{loading.value=false}}async function certify(){const implementations=['python','rust','go'].map(name=>({name,format:'proof-v1',results:{vector1:true}}));try{const r=await cognitiveInfrastructureApi.certify({standard_version:'1.0',proof_type:'decision',implementations,test_vectors:[{id:'vector1'}],revocation_tests:[{rejected:true}]});certificate.value=r.status;ElMessage.success('认证套件运行完成');await load()}catch{ElMessage.error('认证运行失败')}}onMounted(load)</script>
<style scoped>.page{max-width:1260px;margin:auto;padding:28px 24px 48px}.page header{display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid var(--el-border-color);padding-bottom:20px}.page h1{font-size:30px;margin:4px 0 6px;letter-spacing:0}.page header p{margin:0;color:var(--el-text-color-secondary)}.eyebrow{font-size:12px!important;color:var(--el-color-primary)!important;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(10,1fr);margin-bottom:22px}.metrics>div{padding:16px 10px;border-bottom:1px solid var(--el-border-color);border-right:1px solid var(--el-border-color)}.metrics span{display:block;font-size:11px;color:var(--el-text-color-secondary)}.metrics strong{font-size:22px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--el-border-color);border:1px solid var(--el-border-color)}.grid article{background:var(--el-bg-color);padding:24px;min-height:185px}.grid .el-icon{font-size:25px;color:var(--el-color-primary)}.grid h2,.form h2{font-size:17px}.grid p,.form p{color:var(--el-text-color-secondary);line-height:1.6}.form{padding:16px 0}.result{margin-top:24px;border-block:1px solid var(--el-border-color);padding:18px 0}.result span{display:block;color:var(--el-text-color-secondary)}.result strong{font-size:28px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.page{padding:18px 14px}.page h1{font-size:25px}}</style>
